.search {
	display: flex;
	width: 230px;
	height: 32px;
	border-radius: 8px;
	background-color: #424242;
	color: #939393;
	align-items: center;
	margin-left: 100px;
}

.headercontrols {
	display: flex;
	gap: 20px;
	color: #7c7c7c;
	margin-left: 20px;
}

.body {
	display: grid;
	grid-template-columns: 76px 1fr;
}

.menu {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 25px;
	background-color: #222222;
	color: #72aaeb;
	padding-top: 20px;
}

.content {
	background-color: #141414;
}

.back {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	background-color: rgba(0, 0, 0, 0.5);
}

.popup {
	position: absolute;
	top: 72px;
	left: 50%;
	transform: translateX(-50%);
	width: calc(100% - 144px);
	min-height: 70%;
	background-color: #222222;
	color: #fff;
	border-radius: 8px;
	overflow: hidden;
}

.popupcontrols {
	position: absolute;
	top: 72px;
	left: calc(100% - 52px);
	display: inline-flex;
	flex-direction: column;
	gap: 20px;
	opacity: 0.5;
}

.mv_close_icon {
	background-position: 0px 0px;
	width: 20px;
	height: 20px;
	background-image: url(/27c618db4b18814d7939b0e0212b0c89.png);
	background-size: 24px 261px;
}

.mv_minimize_icon {
	background-position: 0 -24px;
	width: 20px;
	height: 5px;
	background-image: url(/27c618db4b18814d7939b0e0212b0c89.png);
	background-size: 24px 261px;
}

.mv_toggle_sideblock_icon {
	background-position: 0 -52px;
	width: 20px;
	height: 19px;
	background-image: url(/27c618db4b18814d7939b0e0212b0c89.png);
	background-size: 24px 261px;
}

.videobuttons {
	display: flex;
	gap: 20px;
	color: #828282;
	border-bottom: 1px solid #363738;
	padding-bottom: 15px;
	margin-bottom: 15px;
}

.controlgroup {
	display: flex;
	align-items: center;
	gap: 5px;
}

.popupcontent {
	display: grid;
	grid-template-columns: 1fr 313px;
}

.videodescription {
	padding: 15px 72px;
	border-right: 1px solid #363738;
}

.videotitle {
	font-size: 17px;
	margin-bottom: 10px;
}

.videostats {
	font-size: 14px;
	color: #828282;
	margin-bottom: 20px;
}

.channelavatar {
	width: 48px;
	height: 48px;
	border-radius: 50%;
}

.channeldescroption {
	display: flex;
	justify-content: space-between;
	align-items: center;
	margin-bottom: 20px;
}

.channeldescroption-left {
	display: flex;
	gap: 15px;
}

.channeldescroption-content {
	display: flex;
	flex-direction: column;
	gap: 5px;
}
.channelname {
	color: #72aaeb;
	font-weight: bold;
}

.channelstats {
	color: #828282;
}

.button-subscribe {
	display: inline-flex;
	gap: 10px;
	align-items: center;
	border-radius: 8px;
	background-color: #e2e3e6;
	color: #222222;
	padding: 4px 10px;
	font-size: 14px;
}

.channeltext {
	font-size: 13px;
}

.player {
	background-color: gray;
	aspect-ratio: 1.78;
	width: 100%;
}

.rightside {
	height: 900px;
}

.cols {
	display: flex;
	gap: 20px;
}

.scrollable {
	overflow: auto;
	max-height: 360px;
	min-height: 20px;
	border: 1px solid #eceaea;
}

